// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testRegression_property() public {
        // No token has been minted, token id 42 does not exist.
        bool ok;
        try c.availableForFlashLoan(address(0x1), 42) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: returns false (because ownerOf reverts -> catch returns false)
        // Buggy: returns true (because catch block incorrectly returns true)
        assertTrue(!ok);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testRegression_property() public {
        // Call availableForFlashLoan with a non-existent token (ownerOf will revert)
        bool available = c.availableForFlashLoan(address(0x123), 999);
        // The reference returns false; the buggy version returns true.
        assertEq(available, false);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testRegression_property() public {
        // Use a non-existent token address and id — the ERC721 at address(this) has no minted tokens
        address fakeNft = address(this);
        uint256 fakeId = 42;
        // The reference returns false because it catches the revert from ownerOf. The buggy version returns true.
        bool canFlash = c.availableForFlashLoan(fakeNft, fakeId);
        assertTrue(!canFlash);
    }
}
